/* بيانات باب tibb: تُحمَّل عند أول فتح للقسم */
window.TIBB = {"ch":[{"id":"asbab","t":"الشفاء من الله والأخذ بالأسباب","d":"أصل الباب: المرض والشفاء بقضاء الله وقدره، ومع ذلك أمر الشرع بالتداوي والحذر وحفظ النفس. هنا مواضع القرآن في ذلك مع الأحاديث الصحيحة الشارحة."},{"id":"asal","t":"العسل والنحل","d":"الموضع الوحيد الذي نصّ فيه القرآن على «شفاء للناس» في شراب يخرج من النحل. وفيه خلاف المفسرين في معنى الضمير وفي عموم الشفاء، فنُورد الخلاف بنصوصه."},{"id":"ghidha","t":"الغذاء والشراب والطيبات","d":"آيات الأكل والشرب: الإباحة والاعتدال والطيبات، وما حرّمه الله من الخبائث والمسكرات، وما ذكره المفسرون من وجوه نفعه أو ضرره."},{"id":"siyam","t":"الصيام والمريض","d":"الصيام فريضة وعبادة، ومعه رخصة المريض في الفطر. نورد ما قاله المفسرون في حكمته بلفظهم، دون أن ننسب إليهم فوائد طبية لم يقولوها."},{"id":"nafs","t":"الصحة النفسية وشفاء الصدور","d":"ما في القرآن مما يتصل بالطمأنينة والسكينة والحزن والرجاء والصبر والنوم والتوكل: ما يقوّي القلب ويزيل القلق بنصوص الآيات وأقوال المفسرين."},{"id":"tahara","t":"الطهارة والنظافة والوقاية","d":"أمر القرآن بالطهارة ومدح المتطهرين، وسمّى الحيض أذى، وجعل الماء طهوراً. نورد بيان المفسرين لهذه المقاصد."},{"id":"hayat","t":"الحمل والرضاعة","d":"ما ذكره القرآن من أحوال الحمل والرضاعة ومددهما، وما تتحمله الأم، وما استنبطه المفسرون من ذلك."}],"i":[{"id":"ib80","ch":"asbab","t":"وإذا مرضت فهو يشفين","r":[26,78,81],"n":"قالها إبراهيم عليه السلام: نسب المرض إلى نفسه والشفاء إلى الله وحده، فالشفاء بيد الله. والأحاديث الصحيحة تؤكد أن لكل داء دواء وأن التداوي مشروع.","hd":1,"qs":[{"w":"السعدي","bk":"saadi","s":26,"ay":80,"x":"الذي خَلَقَني فهو يهديني}: هو [المنْفَرِدُ] بنعمةِ الخَلْق ونعمةِ الهداية للمصالح الدينيَّة والدنيويَّة، ثم خصَّص منها بعضَ الضروريَّات، فقال:{والذي هو يُطۡعِمُنِى ويسقينِ. وإذا مرضت فهو يشفينِ. والذي يُميتُني ثم يحيينِ. والذي أطمعُ أن يَغۡفِرَ لي خطيئتي يومَ الدينِ}: فهذا هو وحدَه المنفردُ بذلك، فيجبُ أن يُفْرَدَ بالعبادةِ والطاعةِ، وتُتْرَكَ هذه الأصنام التي لا تخلقُ ولا تهدي، ولا تمرِضُ ولا تشفي …","en":"He alone is the One Who made creation and guidance, and He singled out some of the necessities, saying: \"And it is He Who feeds me and gives me drink, and when I am ill, it is He Who heals me, and Who causes me to die then gives me life, and Who, I hope, will forgive my sin on the Day of Judgement\". So He alone is unique in that, and so He alone must be singled out for worship and obedience, and these idols must be left, which create not and guide not, make no one ill and heal no one …"}],"h":[{"id":"b5678","b":"bukhari","bn":"صحيح البخاري","n":"5678","x":"مَا أَنْزَلَ اللَّهُ دَاءً إِلاَّ أَنْزَلَ لَهُ شِفَاءً","gr":"","en":"Allah did not send down a disease except that He sent down a cure for it."},{"id":"m2204","b":"muslim","bn":"صحيح مسلم","n":"2204","x":"لِكُلِّ دَاءٍ دَوَاءٌ فَإِذَا أُصِيبَ دَوَاءُ الدَّاءِ بَرَأَ بِإِذْنِ اللَّهِ عَزَّ وَجَلَّ","gr":"","en":"Every disease has a cure; when the cure matches the disease, it heals by the permission of Allah, the Mighty and Majestic."}]},{"id":"ayyub38","ch":"asbab","t":"اركض برجلك: سبب الشفاء من الله","r":[38,41,44],"n":"أمر الله أيوب عليه السلام بأن يضرب الأرض برجله فنبعت عين اغتسل منها وشرب، ثم ختم القصة بقوله «إنا وجدناه صابراً»: الشفاء من الله ويأتي مع أخذ العبد بالسبب الذي يُهيَّأ له.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":38,"ay":42,"x":"فقيل له: {اركُضۡ برِجۡلِكَ}؛ أي: اضربِ الأرض بها؛ لينبعَ لك منها عينٌ تغتسلُ منها وتشربُ، فيذهب عنك الضرُّ والأذى، ففعل ذلك، فذهب عنه الضرُّ وشفاه الله تعالى.","en":"And it was said to him: \"Strike with your foot\", that is, strike the earth with it so that a spring may gush forth for you from which you may wash and drink, and the harm and affliction will leave you. He did so, the harm left him, and Allah the Exalted healed him."}],"h":[]},{"id":"yaqub67","ch":"asbab","t":"الحذر مع التوكل: ادخلوا من أبواب متفرقة","r":[12,67,67],"n":"وصّى يعقوب عليه السلام أبناءه بأخذ سبب الحذر، ثم ردّ الأمر كله إلى الله: «عليه توكلت». فجمع بين السبب والتوكل. وفي الحديث أن الأعراب سألوا النبي ﷺ: أنتداوى؟ فأمرهم بالتداوي.","hd":1,"qs":[{"w":"السعدي","bk":"saadi","s":12,"ay":67,"x":"ثم لما أرسله معهم؛ وصَّاهم إذا هم قدموا مصر أن لا يَدْخلوا {من بابٍ واحد وادخُلوا من أبواب متفرِّقة}: وذلك أنه خاف عليهم العين؛ لكثرتهم وبهاء منظرهم؛ لكونهم أبناء رجل واحد، وهذا سبب، {و} إلا فَ {مَا أغني عنكم من الله}: شيئاً؛ فالمقدَّر لا بدَّ أن يكون. {إن الحكمُ إلا لله}؛ أي: القضاء قضاؤه والأمر أمره؛ فما قضاه، وحكم به لا بدَّ أن يقع. {عليه توكلتُ}؛ أي: اعتمدت على الله لا على ما وصَّيتكم به من السبب.","en":"He then enjoined them, when they reached Egypt, not to enter \"by one gate but enter by different gates\": he feared the evil eye for them because of their large number and fine appearance, as sons of one man, and this is a means, \"and I cannot avail you at all against Allah\", for what is decreed must come to pass. \"The decision is only for Allah\", that is, the judgement is His judgement and the command is His command, so what He has decreed and judged must happen. \"In Him I put my trust\", that is, I relied on Allah and not on the means I advised you to take."}],"h":[{"id":"t2038","b":"tirmidhi","bn":"جامع الترمذي","n":"2038","x":"تَدَاوَوْا فَإِنَّ اللَّهَ لَمْ يَضَعْ دَاءً إِلاَّ وَضَعَ لَهُ شِفَاءً أَوْ قَالَ دَوَاءً إِلاَّ دَاءً وَاحِدًا \" . قَالُوا يَا رَسُولَ اللَّهِ وَمَا هُوَ قَالَ \" الْهَرَمُ","gr":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ بشار عواد معروف: حسن صحيح؛ زبير علي زئي: إسناده صحيح","en":"Seek treatment, for Allah has not placed a disease except that He placed a cure for it—or he said \"a remedy\"—except for one disease.\" They said, \"O Messenger of Allah, what is it?\" He said, \"Old age."}]},{"id":"hifz2195","ch":"asbab","t":"ولا تلقوا بأيديكم إلى التهلكة","r":[2,195,195],"n":"نهى الله عن إلقاء النفس إلى الهلاك، وفسّر السعدي ذلك بترك ما أمر به العبد إذا أدى إلى هلاك البدن، وبفعل ما يوصل إلى تلف النفس. ومن هنا قرر العلماء أن حفظ النفس من مقاصد الشريعة.","hd":1,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":195,"x":"والإلقاء باليد إلى التهلكة يرجع إلى أمرين: ترك ما أمر به العبد إذا كان تركه موجباً أو مقارباً لهلاك البدن أو الروح، وفعل ما هو سبب موصل إلى تلف النفس أو الروح فيدخل تحت ذلك أمور كثيرة، فمن ذلك ترك الجهاد في سبيل الله، أو النفقة فيه الموجب لتسلط الأعداء، ومن ذلك تغرير الإنسان بنفسه في مقاتلة أو سفر مخوف أو محل مسبعة أو حيات، أو يصعد شجراً أو بنياناً خطراً، أو يدخل تحت شيء فيه خطر ونحو ذلك، فهذا ونحوه ممن ألقى بيده إلى التهلكة …","en":"Throwing oneself by one's own hand into destruction comes down to two matters: leaving what the servant was commanded when leaving it causes or nearly causes the destruction of the body or the soul, and doing what is a cause that leads to the ruin of the self or the soul. Many things fall under that. Among them is leaving jihad in the way of Allah, or spending on it, which brings about the domination of enemies; and among them is a person's exposing himself to danger in fighting, or a frightening journey, or a place of beasts or snakes, or climbing a tree or a dangerous building, or going under something dangerous and the like; this and the like is one who has thrown himself by his own hand into destruction"}],"h":[{"id":"b1975","b":"bukhari","bn":"صحيح البخاري","n":"1975","x":"فَإِنَّ لِجَسَدِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِعَيْنِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِزَوْجِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِزَوْرِكَ عَلَيْكَ حَقًّا","gr":"","en":"for your body has a right over you, your eyes have a right over you, your wife has a right over you, and your visitor has a right over you."},{"id":"b6412","b":"bukhari","bn":"صحيح البخاري","n":"6412","x":"نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ، الصِّحَّةُ وَالْفَرَاغُ","gr":"","en":"There are two blessings in which many people are cheated: health and free time."}]},{"id":"nafs429","ch":"asbab","t":"ولا تقتلوا أنفسكم","r":[4,29,29],"n":"نهى الله المؤمنين عن قتل أنفسهم، وبيّن السعدي أن ذلك يشمل الإلقاء بالنفس إلى التهلكة وفعل الأخطار المفضية إلى التلف. وفي السنة: الحذر من الوباء، فلا يُدخل على أرض فيها الطاعون ولا يُخرج منها، ولا يُورد المريض على الصحيح.","hd":1,"qs":[{"w":"السعدي","bk":"saadi","s":4,"ay":29,"x":"ولا تقتلوا أنفسكم}؛ أي: لا يقتل بعضكم بعضاً، ولا يقتل الإنسان نفسه، ويدخل في ذلك الإلقاء بالنفس إلى التهلكة وفعل الأخطار المفضية إلى التلف والهلاك …","en":"\"and do not kill yourselves\", that is, let not some of you kill others, nor let a person kill himself, and that includes throwing oneself into destruction and committing dangerous acts that lead to ruin and destruction"}],"h":[{"id":"b5728","b":"bukhari","bn":"صحيح البخاري","n":"5728","x":"إِذَا سَمِعْتُمْ بِالطَّاعُونِ بِأَرْضٍ فَلاَ تَدْخُلُوهَا، وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلاَ تَخْرُجُوا مِنْهَا","gr":"","en":"If you hear of the plague in a land, do not enter it; and if it breaks out in a land while you are in it, do not leave it."},{"id":"m2221","b":"muslim","bn":"صحيح مسلم","n":"2221","x":"لاَ يُورِدُ مُمْرِضٌ عَلَى مُصِحٍّ","gr":"","en":"A person with sick camels must not bring them to those that are healthy."}]},{"id":"asal1","ch":"asal","t":"يخرج من بطونها شراب مختلف ألوانه","r":[16,68,69],"n":"ذكر الله وحيه إلى النحل وما يخرج من بطونها: شراب مختلف الألوان فيه شفاء للناس. ويذكر المفسرون عناية الله بها وتنوّع العسل بحسب المراعي، وفي الصحيحين أن النبي ﷺ أمر بسقي العسل لمن اشتكى بطنه.","hd":1,"qs":[{"w":"السعدي","bk":"saadi","s":16,"ay":69,"x":"في خلق هذه النَّحلة الصغيرة، التي هداها الله هذه الهداية العجيبة، ويَسَّر لها المراعي، ثم الرجوع إلى بيوتها التي أصلحتها بتعليم الله لها وهدايته لها، ثم يخرج من بطونها هذا العسل اللذيذ مختلف الألوان بحسب اختلاف أرضها ومراعيها؛ فيه شفاء للناس من أمراض عديدة؛ فهذا دليلٌ على كمال عناية الله تعالى وتمام لطفه بعباده، وأنَّه الذي لا ينبغي أن يُحَبَّ غيره، ويُدْعى سواه.","en":"in the creation of this little bee, which Allah guided with this wonderful guidance, and made easy for it the pastures, then its return to the homes it has prepared by Allah's teaching and guidance to it, then there comes out of its belly this delicious honey, of different colours according to the difference of its land and pastures; in it is healing for people from many diseases. So this is a proof of the perfection of Allah's care and the fullness of His kindness to His servants, and that He is the One besides Whom none should be loved, and none else should be called upon."},{"w":"القرطبي","bk":"qurtubi","s":16,"ay":69,"x":"الثَّانِيَةُ- قَوْلُهُ تَعَالَى: ﴿مُخْتَلِفٌ أَلْوانُهُ﴾ يُرِيدُ أَنْوَاعَهُ مِنَ الْأَحْمَرِ وَالْأَبْيَضِ وَالْأَصْفَرِ وَالْجَامِدِ وَالسَّائِلِ، وَالْأُمَّ وَاحِدَةٌ وَالْأَوْلَادُ مُخْتَلِفُونَ دَلِيلٌ عَلَى أَنَّ الْقُدْرَةَ نَوَّعَتْهُ بِحَسَبِ تَنْوِيعِ الْغِذَاءِ، كَمَا يَخْتَلِفُ طَعْمُهُ بِحَسَبِ اخْتِلَافِ الْمَرَاعِي، وَمِنْ هَذَا الْمَعْنَى قَوْلُ زَيْنَبَ لِلنَّبِيِّ ﷺ:\" جَرَسَتْ نَحْلُهُ الْعُرْفُطَ \" حِينَ شَبَّهَتْ رائحته برائحة المغافير.","en":"He means its kinds: red, white and yellow, solid and liquid; the mother is one while the offspring differ, which is a proof that the Power varied it according to the variety of the food, just as its taste differs according to the difference of the pastures; and from this sense is the saying of Zaynab to the Prophet, peace be upon him, \"Its bees fed on the urfut\", when she likened its smell to the smell of maghafir."}],"h":[{"id":"b5680","b":"bukhari","bn":"صحيح البخاري","n":"5680","x":"الشِّفَاءُ فِي ثَلاَثَةٍ شَرْبَةِ عَسَلٍ، وَشَرْطَةِ مِحْجَمٍ، وَكَيَّةِ نَارٍ، وَأَنْهَى أُمَّتِي عَنِ الْكَىِّ","gr":"","en":"Healing is in three: a drink of honey, the cupper's incision, and cauterisation by fire; and I forbid my community from cauterisation."},{"id":"b5684","b":"bukhari","bn":"صحيح البخاري","n":"5684","x":"فَقَالَ أَخِي يَشْتَكِي بَطْنَهُ. فَقَالَ \" اسْقِهِ عَسَلاً \". ثُمَّ أَتَى الثَّانِيَةَ فَقَالَ \" اسْقِهِ عَسَلاً \". ثُمَّ أَتَاهُ فَقَالَ فَعَلْتُ. فَقَالَ \" صَدَقَ اللَّهُ، وَكَذَبَ بَطْنُ أَخِيكَ، اسْقِهِ عَسَلاً \". فَسَقَاهُ فَبَرَأَ","gr":"","en":"He said, \"My brother complains of his stomach.\" He said, \"Give him honey to drink.\" Then he came a second time and he said, \"Give him honey to drink.\" Then he came and said, \"I did.\" He said, \"Allah has spoken the truth and your brother's stomach has lied. Give him honey to drink.\" So he gave it to him and he recovered."}]},{"id":"asal2","ch":"asal","t":"فيه شفاء للناس: إلى أي شيء يعود الضمير؟ وهل الشفاء عام؟","r":[16,69,69],"n":"قال الجمهور: الضمير للعسل. ورُوي عن ابن عباس والحسن ومجاهد أنه للقرآن، وردّه ابن العربي. ثم اختلفوا: هل شفاؤه عام لكل علة ولكل إنسان، أم هو دواء ينفع في بعض الأحوال دون بعض؟ نورد القولين بنصّ القرطبي، وهذا من أمثلة أن الآية لا تُجعل وصفة طبية عامة.","hd":0,"qs":[{"w":"القرطبي","bk":"qurtubi","s":16,"ay":69,"x":"الثَّالِثَةُ- قَوْلُهُ تَعَالَى: ﴿فِيهِ شِفاءٌ لِلنَّاسِ﴾ الضَّمِيرُ لِلْعَسَلِ، قَالَ الْجُمْهُورُ أَيْ فِي الْعَسَلِ شِفَاءٌ لِلنَّاسِ. وَرُوِيَ عَنِ ابْنِ عَبَّاسٍ وَالْحَسَنِ وَمُجَاهِدٍ وَالضَّحَّاكِ وَالْفَرَّاءِ وَابْنِ كَيْسَانَ: الضَّمِيرُ لِلْقُرْآنِ، أَيْ فِي الْقُرْآنِ شِفَاءٌ. النَّحَّاسُ: وَهَذَا قَوْلٌ حَسَنٌ، أَوْ فِيمَا قَصَصْنَا عَلَيْكُمْ مِنَ الْآيَاتِ وَالْبَرَاهِينِ شِفَاءٌ لِلنَّاسِ. وَقِيلَ: الْعَسَلُ فِيهِ شِفَاءٌ، وَهَذَا الْقَوْلُ بَيِّنٌ أَيْضًا، لِأَنَّ أَكْثَرَ الْأَشْرِبَةِ وَالْمَعْجُونَاتِ الَّتِي يُتَعَالَجُ بِهَا أَصْلُهَا مِنَ الْعَسَلِ.","en":"The pronoun refers to honey, said the majority, that is, in honey there is healing for people. And it is related from Ibn Abbas, al-Hasan, Mujahid, al-Dahhak, al-Farra and Ibn Kaysan that the pronoun refers to the Quran, that is, in the Quran there is healing. al-Nahhas said: this is a good view, or in what We have narrated to you of the signs and proofs there is healing for people. And it was said: honey has healing in it, and this view is also clear, because most of the drinks and electuaries with which treatment is given originate from honey."},{"w":"القرطبي","bk":"qurtubi","s":16,"ay":69,"x":"وَقَالَتْ طَائِفَةٌ: إِنَّ ذَلِكَ عَلَى الْخُصُوصِ وَلَا يَقْتَضِي الْعُمُومَ فِي كُلِّ عِلَّةٍ وَفِي كُلِّ إِنْسَانٍ، بَلْ إِنَّهُ خَبَرٌ عَنْ أَنَّهُ يَشْفِي كَمَا يَشْفِي غَيْرُهُ مِنَ الْأَدْوِيَةِ فِي بَعْضٍ وَعَلَى حَالٍ دُونَ حَالٍ، فَفَائِدَةُ الْآيَةِ إِخْبَارٌ مِنْهُ فِي أَنَّهُ دَوَاءٌ لَمَّا كَثُرَ الشِّفَاءُ بِهِ وَصَارَ خَلِيطًا وَمُعِينًا لِلْأَدْوِيَةِ فِي الْأَشْرِبَةِ وَالْمَعَاجِينِ، وَلَيْسَ هَذَا بِأَوَّلِ لَفْظٍ خُصِّصَ فَالْقُرْآنُ مَمْلُوءٌ مِنْهُ وَلُغَةُ الْعَرَبِ يَأْتِي فِيهَا الْعَامُّ كَثِيرًا بِمَعْنَى الْخَاصِّ وَالْخَاصُّ بِمَعْنَى الْعَامِّ. وَمِمَّا يَدُلُّ عَلَى أَنَّهُ لَيْسَ عَلَى الْعُمُومِ أَنَّ\" شِفاءٌ\" نَكِرَةٌ فِي سِيَاقِ الْإِثْبَاتِ، وَلَا عُمُومَ فِيهَا بِاتِّفَاقِ أَهْلِ اللِّسَانِ وَمُحَقِّقِي أَهْلِ الْعِلْمِ وَمُخْتَلِفِي أَهْلِ الْأُصُولِ.","en":"A group said: that is specific and does not imply generality for every illness and every person; rather it is a report that it heals as other medicines heal, in some cases and in one condition rather than another. The benefit of the verse is its report that it is a medicine, since healing by it was frequent and it became a mixture and an aid to medicines in drinks and electuaries. And this is not the first expression to be specified, for the Quran is full of it, and in the language of the Arabs the general often comes with the sense of the specific and the specific with the sense of the general. And among what indicates that it is not general is that \"healing\" is indefinite in an affirmative context, and there is no generality in it by agreement of the people of the language, the verifying scholars and those who differ among the scholars of the principles."}],"h":[]},{"id":"israf","ch":"ghidha","t":"كلوا واشربوا ولا تسرفوا","r":[7,31,31],"n":"أباح الله الأكل والشرب ونهى عن الإسراف. وفسّر السعدي الإسراف بالزيادة على القدر الكافي في المأكولات التي تضر بالجسم، ونقل القرطبي ما قيل في منافع قلة الأكل ومضارّ كثرته، وأورد حديث «ما ملأ آدمي وعاء شراً من بطن».","hd":1,"qs":[{"w":"السعدي","bk":"saadi","s":7,"ay":31,"x":"ثم قال:{وكلوا واشربوا}؛ أي: مما رزقكم الله من الطيبات، {ولا تسرِفوا}: في ذلك، والإسراف إما أن يكون بالزيادة على القدر الكافي والشره في المأكولات التي تضر بالجسم، وإما أن يكون بزيادة الترفُّه والتنوُّق في المآكل والمشارب واللباس، وإما بتجاوز الحلال إلى الحرام. {إنَّه لا يحبُّ المسرفين}: فإن السرف يبغضه الله، ويضرُّ بدن الإنسان ومعيشته، حتى إنه ربما أدَّت به الحالُ إلى أن يعجز عما يجب عليه من النفقات.","en":"Then He said: \"and eat and drink\", that is, of the good things Allah has provided you, \"and do not be excessive\" in that; and excess is either exceeding the sufficient amount and gluttony in foods that harm the body, or increasing luxury and fastidiousness in food, drink and clothing, or going beyond the lawful into the unlawful. \"Indeed, He does not like the excessive\": for excess is hated by Allah, and it harms a person's body and livelihood, so much so that it may bring his condition to the point that he is unable to meet what he is obliged to spend."},{"w":"القرطبي","bk":"qurtubi","s":7,"ay":31,"x":"ثُمَّ قِيلَ: فِي قِلَّةِ الْأَكْلِ مَنَافِعُ كَثِيرَةٌ، مِنْهَا أَنْ يَكُونَ الرَّجُلُ أَصَحَّ جِسْمًا وَأَجْوَدَ حِفْظًا وَأَزْكَى فَهْمًا وَأَقَلَّ نَوْمًا وَأَخَفَّ نَفْسًا. وَفِي كَثْرَةِ الْأَكْلِ كَظُّ الْمَعِدَةِ وَنَتَنُ التُّخْمَةِ ، وَيَتَوَلَّدُ مِنْهُ الْأَمْرَاضُ الْمُخْتَلِفَةُ، فَيَحْتَاجُ مِنَ الْعِلَاجِ أَكْثَرَ مِمَّا يَحْتَاجُ إِلَيْهِ الْقَلِيلُ الْأَكْلِ.","en":"Then it was said: in eating little there are many benefits, among them that a man is healthier in body, better in memory, keener in understanding, less in sleep and lighter in spirit. And in eating much there is the heaviness of the stomach and the foulness of indigestion, and various diseases arise from it, so he needs more treatment than the one who eats little needs."}],"h":[{"id":"i3349","b":"ibnmajah","bn":"سنن ابن ماجه","n":"3349","x":"مَا مَلأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ حَسْبُ الآدَمِيِّ لُقَيْمَاتٌ يُقِمْنَ صُلْبَهُ فَإِنْ غَلَبَتِ الآدَمِيَّ نَفْسُهُ فَثُلُثٌ لِلطَّعَامِ وَثُلُثٌ لِلشَّرَابِ وَثُلُثٌ لِلنَّفَسِ","gr":"الألباني: صحيح؛ شعيب الأرنؤوط: حسن صحيح؛ محمد فؤاد عبد الباقي: صحيح؛ زبير علي زئي: صحيح","en":"The son of Adam fills no vessel worse than his stomach. It is enough for the son of Adam to have a few morsels to keep his back straight; and if the self of the son of Adam overcomes him, then a third for food, a third for drink and a third for breath."}]},{"id":"tayyibat","ch":"ghidha","t":"كلوا من الطيبات حلالاً طيباً","r":[2,168,168],"n":"أمر الله الناس بالأكل مما في الأرض حلالاً طيباً، ونقل السعدي أن الأصل في الأعيان الإباحة وأن المحرّم نوعان: ما حُرّم لذاته وهو الخبيث، وما حُرّم لأمر عارض.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":168,"x":"هذا خطاب للناس كلهم مؤمنهم وكافرهم، فامتن عليهم بأن أمرهم أن يأكلوا من جميع ما في الأرض من حبوب وثمار وفواكه وحيوانات حالة كونها {حلالاً}؛ أي: محللاً لكم تناوله ليس بغصب ولا سرقة ولا محصلاً بمعاملة محرمة أو على وجه محرم أو معيناً على محرم {طيباً}؛ أي: ليس بخبيث كالميتة والدم ولحم الخنزير والخبائث كلها. ففي هذه الآية دليل على أن الأصل في الأعيان الإباحة أكلاً وانتفاعاً وأن المحرم نوعان: إما محرم لذاته وهو الخبيث الذي هو ضد الطيب، وإما محرم لما عرض له وهو المحرم لتعلق حق الله أو حق عباده به، وهو ضد الحلال.","en":"This is an address to all people, believer and disbeliever, and He reminded them of His favour by commanding them to eat of all that is in the earth of grains, fruits, produce and animals, while it is \"lawful\", that is, permitted for you to take, not by usurpation or theft or by a forbidden transaction or by a forbidden means or aiding something forbidden, \"and good\", that is, not foul, like carrion, blood, pork and all foul things. So in this verse is proof that the basic rule for things is permissibility, in eating and in benefit, and that the forbidden is of two kinds: either forbidden in itself, which is the foul that is the opposite of the good, or forbidden for something incidental, which is forbidden because a right of Allah or of His servants attaches to it, and it is the opposite of the lawful."}],"h":[]},{"id":"laban","ch":"ghidha","t":"لبناً خالصاً سائغاً للشاربين","r":[16,66,66],"n":"ذكر الله اللبن من نعمه: يخرج من بين فرث ودم لبناً خالصاً سائغاً للشاربين. ونقل القرطبي عن العلماء أنه أول ما يغتذي به الإنسان وتنمو به الأبدان.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":16,"ay":66,"x":"أي: {إنَّ لكُم في الأنعام}: التي سخَّرها الله لمنافعكم، {لعبرةً}: تستدلُّون بها على كمال قدرة الله وسعة إحسانه؛ حيث أسقاكم من بطونها المشتملة على الفَرْث والدَّم، فأخرج من بين ذلك لبناً خالصاً من الكدر سائغاً للشاربين للذَّته ولأنه يُسقي ويغذي؛ فهل هذه إلاَّ قدرة إلهيَّة لا أمور طبيعيَّة؟! فأي شيء في الطبيعة يقلب العلف الذي تأكُلُه البهيمة والشراب الذي تشربه من الماء العذب والملح لبناً خالصاً سائغاً للشاربين؟!","en":"that is, \"indeed, for you in the livestock\" which Allah has subjected for your benefit \"is a lesson\" by which you may infer the perfection of Allah's power and the breadth of His kindness, in that He gave you drink from their bellies, which contain dung and blood, and brought out from between that milk, pure of impurity, palatable for those who drink, for its pleasantness and because it quenches and nourishes. Is this other than divine power and not natural matters? What in nature turns the fodder that the animal eats and the water, sweet and salty, that it drinks into pure milk, pleasant to drink?"},{"w":"القرطبي","bk":"qurtubi","s":16,"ay":66,"x":"قَالَ عُلَمَاؤُنَا: فَكَيْفَ لَا يَكُونُ ذَلِكَ وَهُوَ أَوَّلُ مَا يَغْتَذِي بِهِ الْإِنْسَانُ وَتَنْمَى بِهِ الْجُثَثُ وَالْأَبْدَانُ، فَهُوَ قُوتٌ خَلِيٌّ عَنِ الْمَفَاسِدِ بِهِ قِوَامُ الْأَجْسَامِ، وَقَدْ جَعَلَهُ اللَّهُ تَعَالَى عَلَامَةً لِجِبْرِيلَ عَلَى هِدَايَةِ هَذِهِ الْأُمَّةِ الَّتِي هِيَ خَيْرُ الْأُمَمِ أُمَّةً، فَقَالَ فِي الصَّحِيحِ:\" فَجَاءَنِي جِبْرِيلُ بِإِنَاءٍ مِنْ خَمْرٍ وَإِنَاءٍ مِنْ لَبَنٍ فَاخْتَرْتُ اللَّبَنَ فَقَالَ لِي جِبْرِيلُ اخْتَرْتَ الْفِطْرَةَ أَمَا إِنَّكَ لَوِ اخْتَرْتَ الْخَمْرَ غَوَتْ أُمَّتُكَ (.","en":"Our scholars said: how could it not be so, when it is the first thing a human is nourished by and bodies grow through, so it is a food free of defects by which the bodies are sustained, and Allah made it a sign for Jibril of the guidance of this community, which is the best of communities, for he said in the Sahih: \"Jibril came to me with a vessel of wine and a vessel of milk, and I chose the milk. Jibril said to me: you chose the natural way; had you chosen wine, your community would have gone astray\"."}],"h":[]},{"id":"ma21","ch":"ghidha","t":"وجعلنا من الماء كل شيء حي","r":[21,30,30],"n":"جعل الله الماء أصل الحياة: السماء بالمطر والأرض بالنبات. وهذه آية في أصل الغذاء والشراب، ومن هذا الماء يكون الطعام والشراب لكل حي.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":21,"ay":30,"x":"أي: أولم ينظُر هؤلاء الذين كفروا بربِّهم، وجَحَدوا الإخلاص له في العبوديَّة ما يدلُّهم دلالةَ مشاهدةٍ على أنه الربُّ المحمود الكريم المعبود، فيشاهدون السماء والأرض، فيجدونهما {رتقاً}؛ هذه ليس فيها سحابٌ ولا مطرٌ، وهذه هامدةٌ ميتةٌ لا نبات فيها، {ففتقناهما}؛ السماء بالمطر، والأرض بالنبات. أليس الذي أوجَدَ في السماء السحاب بعد أن كان الجوُّ صافياً لا قَزَعَةَ فيه، وأودَعَ فيه الماء الغزير، ثم ساقه إلى بلدٍ ميِّتٍ قد اغبرَّت أرجاؤه وقحط عنه ماؤه، فأمطره فيها، فاهتزَّت وتحرَّكت ورَبَتْ وأنبتت من كلِّ زوج بهيج مختلفِ الأنواع متعددِ المنافع …","en":"that is, have those who disbelieved in their Lord and denied sincerity to Him in worship not seen what shows them, as a matter of observation, that He is the praiseworthy, generous Lord, the One worshipped, as they observe the heaven and the earth and find them \"closed up\": this one has no cloud or rain, and that one is barren and dead, with no vegetation, \"then We opened them\", the heaven with rain and the earth with plants. Is it not He Who brought into being the cloud in the sky after the air was clear with not a wisp in it, and deposited in it abundant water, then drove it to a dead land whose horizons had grown dusty and from which water was withheld, and sent rain on it, and it stirred, swelled and grew every kind of beautiful plant, varied in kinds, many in benefits …"}],"h":[]},{"id":"zaytun","ch":"ghidha","t":"شجرة الزيتون: دهن وصبغ للآكلين","r":[23,20,20],"n":"ذكر الله شجرة الزيتون التي تنبت بالدُّهن وصبغٍ للآكلين، وأشار السعدي إلى ما فيها من منافع: الزيت للاستصباح والإدام.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":23,"ay":20,"x":"{وشجرة تخرج من طور سَيۡناءَ}: وهي شجرة الزيتون؛ أي: جنسها، خُصَّت بالذكر لأنَّ مكانها خاصٌّ في أرض الشام، ولمنافعها التي ذُكِرَ بعضُها في قوله:{تَنۡبُتُ بالدُّهن وصِبۡغٍ للآكلين}؛ أي: فيها الزيت الذي هو دهنٌ، يُسْتَعْمَلُ استعمالَه من الاستصباح به، واصطباغ للآكلين؛ أي: يجعل إداماً للآكلين وغير ذلك من المنافع.","en":"It is the olive tree, that is, its kind, singled out for mention because its place is particular to the land of Sham and because of its benefits, some of which are mentioned in His saying \"which grows with oil and a condiment for those who eat\", that is, in it is the oil, which is a fat, used in the way fat is used, for lighting and as a dip for those who eat, that is, it is made an accompaniment for those who eat, and other benefits."}],"h":[]},{"id":"rutab","ch":"ghidha","t":"هزّي إليك بجذع النخلة تساقط عليك رطباً جنياً","r":[19,25,26],"n":"أمر الله مريم عليها السلام وهي في حال الولادة أن تهزّ جذع النخلة فيتساقط عليها الرطب. ونقل القرطبي عن الربيع بن خثيم أن الرطب أنفع ما للنفساء لهذه الآية، وذكر أن التمر صار عادة للنفساء، وأن هذا قولٌ لا حديثٌ نبوي.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":19,"ay":25,"x":"{وهُزِّي إليك بجذع النخلةِ تُساقِطۡ عليك رُطَباً جنيًّا}؛ أي: طريًّا لذيذاً نافعاً.","en":"\"And shake toward yourself the trunk of the palm tree; it will drop upon you ripe, fresh dates\", that is, fresh, delicious and beneficial."},{"w":"القرطبي","bk":"qurtubi","s":19,"ay":25,"x":"الرَّابِعَةُ- قَالَ الرَّبِيعُ بْنُ خَيْثَمٍ: مَا لِلنُّفَسَاءِ عِنْدِي خَيْرٌ مِنَ الرُّطَبِ لِهَذِهِ الْآيَةِ، وَلَوْ عَلِمَ اللَّهُ شَيْئًا هُوَ أَفْضَلُ مِنَ الرُّطَبِ لِلنُّفَسَاءِ لَأَطْعَمَهُ مَرْيَمَ وَلِذَلِكَ قَالُوا: التَّمْرُ عَادَةٌ لِلنُّفَسَاءِ مِنْ ذَلِكَ الْوَقْتِ وَكَذَلِكَ التَّحْنِيكُ. وَقِيلَ: إِذَا عَسِرَ وِلَادُهَا لَمْ يَكُنْ لَهَا خَيْرٌ مِنَ الرُّطَبِ وَلَا لِلْمَرِيضِ خَيْرٌ مِنَ الْعَسَلِ، ذَكَرَهُ الزَّمَخْشَرِيُّ.","en":"al-Rabi ibn Khuthaym said: I know nothing better for a woman after childbirth than fresh dates because of this verse, and had Allah known anything better for a woman after childbirth than fresh dates, He would have fed it to Maryam; and for that reason they said: dates are a custom for a woman after childbirth from that time, and likewise the tahnik. And it was said: when her delivery is difficult, nothing is better for her than fresh dates, and nothing is better for the sick than honey; al-Zamakhshari mentioned it."}],"h":[]},{"id":"mayta","ch":"ghidha","t":"حُرّمت الميتة والدم ولحم الخنزير","r":[5,3,3],"n":"حرّم الله الميتة والدم ولحم الخنزير وما أُهلّ لغير الله به. وبيّن السعدي أن الله لا يحرّم إلا صيانةً لعباده وحمايةً من الضرر الموجود في المحرمات، وقد يُبيّن ذلك وقد لا يُبيّن، وفسّر ضرر الميتة بكلامه.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":5,"ay":3,"x":"واعلم أن الله تبارك وتعالى لا يحرِّم ما يحرِّم إلاَّ صيانةً لعباده وحمايةً لهم من الضرر الموجود في المحرَّمات، وقد يبين للعبادِ ذلك وقد لا يبين، فأخبر أنه حرَّم {الميتة}، والمراد بالميتة ما فُقدت حياته بغير ذكاة شرعيَّة؛ فإنَّها تحرُم لضررها، وهو احتقان الدم في جوفها ولحمها المضرِّ بآكلها، وكثيراً ما تموت بعلةٍ تكون سبباً لهلاكها فتضرُّ بالآكل …","en":"And know that Allah, Blessed and Exalted, does not forbid what He forbids except to protect His servants and shield them from the harm that exists in the forbidden things; He may make that clear to the servants and may not. So He reported that He forbade \"carrion\", and what is meant by carrion is what lost its life without a lawful slaughter, for it is forbidden because of its harm, which is the congestion of the blood within its body and its meat, harmful to the one who eats it, and it often dies of an illness that is a cause of its destruction, so it harms the eater"}],"h":[]},{"id":"khamr","ch":"ghidha","t":"الخمر والميسر: إثم كبير ومنافع للناس","r":[2,219,219],"n":"ذكر الله أن في الخمر والميسر «إثم كبير ومنافع للناس» وأن إثمهما أكبر من نفعهما، ثم حرّمهما في المائدة. ويبيّن السعدي ما يصدر عن الخمر من ذهاب العقل والمال والعداوة، وهذا من لطف الله بالتدرج في التحريم.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":219,"x":"فأخبر أن إثمهما ومضارهما وما يصدر عنهما من ذهاب العقل والمال والصد عن ذكر الله وعن الصلاة والعداوة والبغضاء …","en":"So He reported that their sin and harms and what issues from them of the loss of reason and wealth, and turning away from the remembrance of Allah and from prayer, and enmity and hatred"},{"w":"السعدي","bk":"saadi","s":5,"ay":90,"x":"فإنَّ في الخمر من انقلاب العقل وذهاب حجاه ما يدعو إلى البغضاء بينه وبين إخوانه المؤمنين …","en":"for in wine there is such a reversal of the mind and loss of its restraint that calls to hatred between him and his believing brothers"}],"h":[]},{"id":"siyam183","ch":"siyam","t":"كُتب عليكم الصيام لعلكم تتقون","r":[2,183,183],"n":"فرض الله الصيام وبيّن حكمته: «لعلكم تتقون». ونقل السعدي وجوه ذلك: ترك الأكل والشرب تقرباً إلى الله، ومراقبة الله، وتضييق مجاري الشيطان، وكثرة الطاعة، ومواساة الفقراء. والحكمة المنصوص عليها تقوى القلب، ولم يقل المفسر هنا شيئاً عن فوائده الطبية.","hd":1,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":183,"x":"ثم ذكر تعالى حكمته في مشروعية الصيام فقال:{لعلكم تتقون}؛ فإن الصيام من أكبر أسباب التقوى لأن فيه امتثال أمر الله واجتناب نهيه، فممِّا اشتمل عليه من التقوى أن الصائم يترك ما حرم الله عليه من الأكل والشرب والجماع ونحوها التي تميل إليها نفسه متقرباً بذلك إلى الله راجياً بتركها ثوابه، فهذا من التقوى، ومنها: أن الصائم يدرب نفسه على مراقبة الله تعالى فيترك ما تهوى نفسه مع قدرته عليه لعلمه باطلاع الله عليه، ومنها: أنَّ الصيام يضيق مجاري الشيطان فإنه يجري من ابن ادم مجرى الدم فبالصيام يضعف نفوذه وتقل منه المعاصي …","en":"Then He mentioned the wisdom of the legislation of fasting, saying: \"that you may become righteous\"; for fasting is among the greatest causes of piety, because in it is obeying Allah's command and avoiding His prohibition. Among the piety it contains is that the fasting person leaves what Allah forbade him, of eating, drinking, intercourse and the like, which his soul inclines to, seeking nearness to Allah by it, hoping for His reward by leaving it, and this is piety. And among it is that the fasting person trains himself in being watchful of Allah, so he leaves what his soul desires while able to have it, because he knows Allah sees him. And among it is that fasting narrows the channels of the devil, for he flows in the son of Adam as blood flows, so by fasting his reach weakens and sins become fewer"}],"h":[{"id":"b1894","b":"bukhari","bn":"صحيح البخاري","n":"1894","x":"الصِّيَامُ جُنَّةٌ، فَلاَ يَرْفُثْ وَلاَ يَجْهَلْ","gr":"","en":"Fasting is a shield, so let him not speak obscenely nor act foolishly."},{"id":"b5066","b":"bukhari","bn":"صحيح البخاري","n":"5066","x":"يَا مَعْشَرَ الشَّبَابِ مَنِ اسْتَطَاعَ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ، وَأَحْصَنُ لِلْفَرْجِ، وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ، فَإِنَّهُ لَهُ وِجَاءٌ","gr":"","en":"O young men, whoever among you is able to marry, let him marry, for it lowers the gaze and protects chastity; and whoever is unable, let him fast, for it is a restraint for him."}]},{"id":"rukhsa185","ch":"siyam","t":"يريد الله بكم اليسر: رخصة المريض","r":[2,184,185],"n":"رخّص الله للمريض والمسافر في الفطر ثم القضاء، وختم بقوله «يريد الله بكم اليسر ولا يريد بكم العسر». وهذا أصل في مراعاة العلة البدنية: التكليف مرفوع حيث يُلحق ضرراً، وتفاصيل أحكام المريض في الصيام في باب الفقه.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":185,"x":"فمن شهد منكم الشهر فليصمه}؛ هذا فيه تعيين الصيام على القادر الصحيح الحاضر، ولما كان النسخ للتخيير بين الصيام والفداء خاصة، أعاد الرخصة للمريض والمسافر لئلا يتوهم أن الرخصة أيضاً منسوخة فقال:{يريد الله بكم اليسر ولا يريد بكم العسر}؛ أي: يريد الله تعالى أن ييسر عليكم الطرق الموصلة إلى رضوانه أعظم تيسير ويسهلها أبلغ تسهيل، ولهذا كان جميع ما أمر الله به عباده في غاية السهولة في أصله، وإذا حصلت بعض العوارض الموجبة لثقله؛ سهله تسهيلاً آخر إما بإسقاطه أو تخفيفه بأنواع التخفيفات، وهذه جملة لا يمكن تفصيلها، لأن تفاصيلها جميع الشرعيات، ويدخل فيها جميع الرخص والتخفيفات …","en":"\"So whoever witnesses the month among you, let him fast it\": this is the specification of fasting for the one able, healthy and present; and since the abrogation was of the choice between fasting and the ransom only, He restored the concession for the sick and the traveller lest someone suppose that the concession too was abrogated, so He said: \"Allah intends for you ease and does not intend for you hardship\", that is, Allah the Exalted intends to make easy for you the paths that lead to His pleasure, with the greatest ease, and to make them smooth with the fullest smoothness; and so everything Allah commanded His servants is very easy in its origin, and if some circumstances arise that make it heavy, He eased it another way, either by waiving it or lightening it with kinds of lightening, and this is a sum that cannot be detailed, for its details are all the legal rulings, and all concessions and lightenings enter into it"}],"h":[]},{"id":"ittmi","ch":"nafs","t":"ألا بذكر الله تطمئن القلوب","r":[13,28,28],"n":"جعل الله ذكره سبب طمأنينة القلوب. وفسّر السعدي الطمأنينة بزوال القلق والاضطراب، وذكر أن لا شيء ألذّ للقلوب من محبة خالقها والأنس به.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":13,"ay":28,"x":"ثم ذكر تعالى علامة المؤمنين، فقال:{الذين آمنوا وتطمئنُّ قلوبُهم بذكر الله}؛ أي: يزول قلقها واضطرابها، وتحضُرُها أفراحها ولذَّاتها. {ألا بذكرِ الله تطمئنُّ القلوب}؛ أي: حقيق بها وحريٌّ أن لا تطمئنَّ لشيءٍ سوى ذكره؛ فإنَّه لا شيء ألذُّ للقلوب ولا أشهى ولا أحلى من محبة خالقها والأنس به ومعرفته …","en":"Then He mentioned the sign of the believers, so He said: \"Those who believe and whose hearts find peace in the remembrance of Allah\", that is, their anxiety and agitation vanish, and their joys and pleasures are present. \"Verily, in the remembrance of Allah do hearts find peace\", that is, it is fitting and proper that they find peace in nothing but His remembrance, for there is nothing sweeter to hearts, nor more longed for, nor more pleasant than the love of their Creator, intimacy with Him and knowledge of Him"}],"h":[]},{"id":"sadr","ch":"nafs","t":"قد جاءتكم موعظة من ربكم وشفاء لما في الصدور","r":[10,57,57],"n":"وصف الله القرآن بأنه شفاء لما في الصدور. وفسّره السعدي بشفاء أمراض الشهوات وأمراض الشبهات، وفسّره البغوي بأنه دواء للجهل. وهذا شفاء القلوب، والرقية بالقرآن لها بابها في «التداوي بالقرآن».","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":10,"ay":57,"x":"وشفاءٌ لما في الصدور}: وهو هذا القرآن، شفاءٌ لما في الصدور من أمراض الشهوات الصَّادة عن الانقياد للشرع، وأمراض الشُّبهات القادحة في العلم اليقينيِّ …","en":"\"and a healing for what is in the breasts\": and it is this Quran, a healing for what is in the breasts of the diseases of desires that bar submission to the Law, and the diseases of doubts that undermine certain knowledge"},{"w":"البغوي","bk":"baghawi","s":10,"ay":57,"x":"قَوْلُهُ تَعَالَى: ﴿يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ﴾ تَذْكِرَةٌ، ﴿مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ﴾ أَيْ: دَوَاءٌ لِلْجَهْلِ، لِمَا فِي الصُّدُورِ.","en":"His saying, Exalted: \"O people, there has come to you an admonition from your Lord\", a reminder, \"and a healing for what is in the breasts\", that is: a remedy for ignorance, for what is in the breasts."}],"h":[]},{"id":"sakina","ch":"nafs","t":"هو الذي أنزل السكينة في قلوب المؤمنين","r":[48,4,4],"n":"ذكر الله أنه أنزل السكينة في قلوب المؤمنين. وبيّن السعدي أنها السكون والطمأنينة والثبات عند المحن المقلقة التي تشوّش القلوب وتضعف النفوس.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":48,"ay":4,"x":"يخبر تعالى عن منَّته على المؤمنين بإنزال السكينة في قلوبهم، وهي السكونُ والطمأنينةُ والثباتُ عند نزول المحنِ المقلقةِ والأمور الصعبة التي تشوِّشُ القلوبَ وتزعجُ الألباب وتضعِفُ النفوس؛ فمن نعمة الله على عبده في هذه الحال أن يثبِّتَه ويربطَ على قلبه، وينزِلَ عليه السكينةَ، ليتلقَّى هذه المشقَّاتِ بقلبٍ ثابتٍ ونفس مطمئنةٍ، فيستعدَّ بذلك لإقامة أمر الله في هذه الحال، فيزداد بذلك إيمانُه، ويتمَّ إيقانُه.","en":"He reports of His favour upon the believers by sending down tranquillity into their hearts, which is calm, peace and steadfastness when disquieting trials and hard matters descend that disturb hearts, unsettle minds and weaken souls; so it is among Allah's blessings upon His servant in this condition that He steadies him, binds his heart and sends down tranquillity on him, so that he meets these hardships with a steady heart and a tranquil soul, and thereby prepares to establish Allah's command in this condition, so his faith increases and his certainty is completed."}],"h":[]},{"id":"hazan","ch":"nafs","t":"ولا تهنوا ولا تحزنوا","r":[3,139,139],"n":"خاطب الله المؤمنين بعد الهزيمة: «ولا تهنوا ولا تحزنوا». وبيّن السعدي أن الحزن في القلوب والوهن في الأبدان زيادة مصيبة، وأمرهم بتشجيع قلوبهم ودفع الحزن عنها.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":3,"ay":139,"x":"ولا تهنوا ولا تحزنوا}؛ أي: ولا تهنوا وتضعفوا في أبدانكم، ولا تحزنوا في قلوبكم عندما أصابتكم المصيبة، وابتليتم بهذه البلوى، فإن الحزن في القلوب والوهن على الأبدان زيادة مصيبة عليكم، وعون لعدوكم عليكم بل شجعوا قلوبكم وصبروها وادفعوا عنها الحزن …","en":"that is, do not grow weak and feeble in your bodies, and do not grieve in your hearts when the calamity befell you and you were tried by this trial, for grief in the hearts and weakness in the bodies are an added calamity upon you, and a help to your enemy against you; rather, encourage your hearts, make them patient and drive grief away from them"}],"h":[]},{"id":"yusr","ch":"nafs","t":"فإن مع العسر يسراً","r":[94,5,6],"n":"بشّر الله بأن اليسر يصاحب العسر ويقارنه، وبيّن السعدي بلاغة اللفظ في أن اليسر يتكرر والعسر واحد. وهذا أصل في الرجاء وعلاج اليأس.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":94,"ay":5,"x":"إنَّ مع العُسۡرِ يُسۡراً}: بشارةٌ عظيمةٌ أنَّه كلَّما وُجِدَ عسرٌ وصعوبةٌ؛ فإنَّ اليسر يقارنه ويصاحبه، حتى لو دخل العسر جحر ضبٍّ؛ لدخل عليه اليسر فأخرجه؛ كما قال تعالى:{سيجعل اللهُ بعدَ عُسۡرٍ يُسۡراً}، وكما قال النبيُّ - صلى الله عليه وسلم -: «وإنَّ الفرج مع الكرب، وإنَّ مع العسر يسراً ». وتعريف العسر في الآيتين يدلُّ على أنَّه واحدٌ، وتنكير اليسرِ يدلُّ على تكراره؛ فلن يغلب عسرٌ يسرين.","en":"\"Indeed, with hardship comes ease\": a great glad tidings that whenever there is hardship and difficulty, ease accompanies it and goes with it, even if hardship were to enter a lizard's hole, ease would enter after it and bring it out; as Allah said: \"Allah will bring about, after hardship, ease\", and as the Prophet, peace and blessings be upon him, said: \"The relief comes with the distress, and with hardship is ease\". And the definiteness of hardship in the two verses indicates that it is one, and the indefiniteness of ease indicates its repetition, so one hardship will not overcome two eases."}],"h":[]},{"id":"raja","ch":"nafs","t":"ولا تيأسوا من روح الله","r":[12,87,87],"n":"قالها يعقوب عليه السلام لبنيه وهو في حزن شديد: لا يأس مع الرجاء. وبيّن السعدي أن الرجاء يوجب السعي والاجتهاد، واليأس يوجب التثاقل والتباطؤ.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":12,"ay":87,"x":"أي: قال يعقوب عليه السلام لبنيه: {يا بَنِيَّ اذهبوا فتحسَّسوا من يوسف وأخيه}؛ أي: احرصوا واجتهدوا على التفتيش عنهما، {ولا تيأسوا من رَوۡح الله}: فإنَّ الرجاء يوجِبُ للعبد السعي والاجتهاد فيما رجاه، والإياس يوجِبُ له التثاقل والتباطؤ، وأولى ما رجا العبادُ فضل الله وإحسانه ورحمته وروحه. {إنَّه لا ييأسُ من رَوۡح الله إلاَّ القومُ الكافرون}: فإنَّهم لكفرِهم يستبعدون رحمتَه، ورحمتُه بعيدةٌ منهم؛ فلا تتشبَّهوا بالكافرين.","en":"that is, Yaqub, peace be upon him, said to his sons: \"My sons, go and find out about Yusuf and his brother\", that is, strive and exert yourselves to search for them; \"and do not despair of the mercy of Allah\": for hope impels the servant to effort and striving in what he hopes for, and despair impels him to heaviness and slowness; and the most deserving thing for servants to hope for is Allah's grace, His kindness, His mercy and His relief. \"Indeed, no one despairs of the mercy of Allah except the disbelieving people\": for in their disbelief they think His mercy far off, and His mercy is far from them, so do not resemble the disbelievers."}],"h":[]},{"id":"qanat","ch":"nafs","t":"لا تقنطوا من رحمة الله","r":[39,53,53],"n":"نادى الله عباده المسرفين على أنفسهم: «لا تقنطوا من رحمة الله». وفسّر السعدي القنوط بأنه اليأس الذي يُلقي بصاحبه إلى الهلاك، ودعا إلى معرفة الله بأسمائه الدالة على كرمه.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":39,"ay":53,"x":"لا تَقۡنَطوا من رحمةِ الله}؛ أي: لا تيأسوا منها، فَتُلْقوا بأيديكم إلى التَّهْلُكَه …","en":"\"do not despair of the mercy of Allah\", that is, do not give up hope of it, so as to throw yourselves into destruction"}],"h":[]},{"id":"taha","ch":"nafs","t":"ما أنزلنا عليك القرآن لتشقى","r":[20,1,2],"n":"نفى الله أن يكون القرآن لشقاء العبد، وفسّر السعدي ذلك بأنه شُرع رحمةً وسهّله غاية التسهيل وجعله غذاءً للقلوب والأرواح وراحةً للأبدان.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":20,"ay":2,"x":"وإنَّما الوحي والقرآن والشرع شَرَعَهُ الرحيم الرحمن، وجَعَلَهُ موصلاً للسعادة والفلاح والفوز، وسهَّله غايةَ التسهيل، ويسَّر كلَّ طرقه وأبوابه، وجعله غذاء للقلوب والأرواح وراحةً للأبدان …","en":"Rather, the revelation, the Quran and the Law were legislated by the Compassionate, the Merciful, Who made it a means to happiness, success and triumph, and made it easy to the utmost, and made easy all its ways and doors, and made it food for hearts and souls and rest for bodies"}],"h":[]},{"id":"sabr155","ch":"nafs","t":"ولنبلونكم بشيء من الخوف والجوع … وبشر الصابرين","r":[2,155,157],"n":"أخبر الله أنه يبتلي عباده بالخوف والجوع ونقص الأموال والأنفس والثمرات، وبشّر الصابرين. وبيّن السعدي حال الصابر والجازع، وأن المصيبة قد تكون نعمة في حق الصابر.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":155,"x":"وأما من وفقه الله للصبر عند وجود هذه المصائب فحبس نفسه عن التسخط قولاً وفعلاً واحتسب أجرها عند الله وعلم أن ما يدركه من الأجر بصبره أعظم من المصيبة التي حصلت له، بل المصيبة تكون نعمة في حقه لأنها صارت طريقاً لحصول ما هو خير له وأنفع منها، فقد امتثل أمر الله وفاز بالثواب، فلهذا قال تعالى:{وبشر الصابرين}؛ أي: بشرهم بأنهم يوفون أجرهم بغير حساب، فالصابرون هم الذين فازوا بالبشارة العظيمة والمنحة الجسيمة، ثم وصفهم بقوله …","en":"As for the one whom Allah enables to be patient when these calamities occur, he restrains himself from displeasure in word and deed, seeks its reward with Allah and knows that the reward he attains by his patience is greater than the calamity that befell him; indeed the calamity becomes a blessing for him, because it became a path to something better and more beneficial than it, so he has obeyed Allah's command and won the reward. Hence He said: \"and give good tidings to the patient\", that is, give them the good news that they will be given their reward without account, so the patient are those who have won the great glad tidings and the weighty gift; then He described them by His saying:"}],"h":[]},{"id":"nawm","ch":"nafs","t":"وجعلنا نومكم سباتاً","r":[78,9,11],"n":"ذكر الله النوم والليل من نعمه: راحة ونقطاع للحركة. وفسّره السعدي وابن كثير بأن الأبدان تتعب من الحركة المستمرة فيجعل الله النوم راحة لها.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":78,"ay":9,"x":"وجَعَلۡنا نومَكم سُباتاً}؛ أى: راحةً لكم وقطعاً لأشغالكم التي متى تمادت بكم؛ أضرَّت بأبدانكم، فجعل الله الليل والنوم يُغْشي الناس لتسكنَ حركاتُهم الضارَّة وتحصل راحتُهم النافعةُ …","en":"that is, rest for you and a cutting off of your tasks, which if they continued would harm your bodies, so Allah made the night and sleep cover the people so that their harmful movements are stilled and their beneficial rest is attained"},{"w":"ابن كثير","bk":"ibnkathir","s":25,"ay":47,"x":"﴿وَالنَّوْمَ سُبَاتًا﴾ أَيْ: قَطْعَا لِلْحَرَكَةِ لِرَاحَةِ الْأَبْدَانِ، فَإِنَّ الْأَعْضَاءَ وَالْجَوَارِحَ تَكِلُّ مِنْ كَثْرَةِ الْحَرَكَةِ فِي الِانْتِشَارِ بِالنَّهَارِ فِي الْمَعَايِشِ، فَإِذَا جَاءَ اللَّيْلُ وَسَكَنَ سَكَنَتِ الْحَرَكَاتُ، فَاسْتَرَاحَتْ فَحَصَلَ النَّوْمُ الَّذِي فِيهِ رَاحَةُ الْبَدَنِ وَالرُّوحِ مَعًا.","en":"\"and sleep as a rest\", that is, a cutting off of movement for the rest of the bodies, for the limbs and organs grow weary from much movement in spreading out by day for livelihoods; so when night comes and settles, movements settle and rest, and sleep occurs, in which is the rest of body and soul together."}],"h":[]},{"id":"tawakkul","ch":"nafs","t":"ومن يتوكل على الله فهو حسبه","r":[65,2,3],"n":"وعد الله من يتوكل عليه بأن يكفيه. وبيّن السعدي معنى التوكل: الاعتماد على الله في جلب ما ينفع ودفع ما يضر مع الثقة بتيسيره، وهو من أسباب سكون القلب.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":65,"ay":3,"x":"ومن يَتَوَكَّلۡ على الله}: في أمر دينه ودنياه؛ بأن يعتمد على الله في جلب ما ينفعه ودفع ما يضرُّه ويثق به في تسهيل ذلك {فهو حسبُه}؛ أي: كافيه الأمر الذي توكَّل عليه فيه …","en":"\"and whoever relies upon Allah\" in the matter of his religion and his worldly life, by relying on Allah in bringing what benefits him and repelling what harms him and trusting Him to make that easy, \"then He is sufficient for him\", that is, sufficient for him in the matter he relied on Him for"}],"h":[]},{"id":"wudu","ch":"tahara","t":"ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم","r":[5,6,6],"n":"ختم الله آية الوضوء والغسل والتيمم بأنه لا يريد الحرج بل يريد تطهير عباده وإتمام نعمته. وعدّ السعدي ذلك من الأحكام المستنبطة من الآية: التشريع رحمة.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":5,"ay":6,"x":"الثامن والأربعون: أنَّ الله تعالى فيما شرعه لنا من الأحكام لم يجعل علينا في ذلك من حَرَج ولا مشقَّةٍ ولا عُسر، وإنَّما هو رحمةٌ منه بعباده ليطِّهرَهم وليتمَّ نعمتَه عليهم …","en":"The forty-eighth: that Allah, in the rulings He legislated for us, did not place upon us any hardship, difficulty or distress, but it is a mercy from Him to His servants, to purify them and to complete His favour upon them"}],"h":[]},{"id":"mahid","ch":"tahara","t":"ويسألونك عن المحيض قل هو أذى","r":[2,222,222],"n":"سمّى الله المحيض أذى وأمر باعتزال النساء فيه حتى يطهرن. وبيّن السعدي أنه لما كان أذىً كان من الحكمة منع العباد عنه، وأن المنع لطف بهم.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":222,"x":"فأخبر تعالى أن الحيض أذى وإذا كان أذى فمن الحكمة أن يمنع الله تعالى عباده عن الأذى وحده …","en":"So He reported that menstruation is an impurity, and if it is an impurity then it is of wisdom that Allah forbids His servants from the impurity alone"}],"h":[]},{"id":"tatahhur","ch":"tahara","t":"فيه رجال يحبون أن يتطهروا والله يحب المطّهرين","r":[9,108,108],"n":"مدح الله أهل قباء الذين يحبون التطهر وأخبر أنه يحب المطهرين. وبيّن السعدي أن الطهارة معنوية وحسّية: التنزه من الشرك والأخلاق الرذيلة، وإزالة الأنجاس ورفع الأحداث.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":9,"ay":108,"x":"وسألهم النبيُّ - صلى الله عليه وسلم - بعدما نزلت هذه الآية في مدحهم عن طهارتهم؟ فأخبروه أنَّهم يُتْبِعون الحجارة الماء، فحمدهم على صنيعهم.{والله يحبُّ المطَّهِّرين}: الطهارة المعنوية كالتنزُّه من الشرك والأخلاق الرذيلة، والطهارة الحسيَّة كإزالة الأنجاس ورفع الأحداث.","en":"And the Prophet, peace and blessings be upon him, asked them after this verse was revealed in praise of them about their purification. They told him that they follow stones with water, so he praised them for what they did. \"And Allah loves those who purify themselves\": moral purification such as freeing oneself from shirk and base characters, and physical purification such as removing impurities and lifting states of ritual impurity."}],"h":[]},{"id":"thiyab","ch":"tahara","t":"وثيابك فطهّر","r":[74,4,4],"n":"من أوائل ما نزل: الأمر بتطهير الثياب. وذكر السعدي احتمالين: أن المراد الأعمال كلها، أو الثياب المعروفة فتُطهَّر من النجاسات في كل وقت.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":74,"ay":4,"x":"{وثيابَكَ فطَهِّرۡ}: يُحتمل أنَّ المراد بالثياب أعماله كلها. وبتطهيرها: تخليصها، والنُّصح بها، وإيقاعها على أكمل الوجوه، وتنقيتها عن المبطلات والمفسدات والمنقصات من شركٍ ورياء ونفاق وعُجْبٍ وتكبُّر وغفلةٍ وغير ذلك مما يؤمَرُ العبد باجتنابه في عباداته، ويدخل في ذلك تطهير الثياب من النجاسة؛ فإنَّ ذلك من تمام التطهير للأعمال، خصوصاً في الصلاة، التي قال كثيرٌ من العلماء: إنَّ إزالة النجاسة عنها شرطٌ من شروطها. ويُحتمل أنَّ المراد بثيابه الثياب المعروفة؛ أنَّه مأمورٌ بتطهيرها عن جميع النجاسات في جميع الأوقات، خصوصاً عند الدُّخول في الصلوات.","en":"\"And your clothing purify\": it may be that clothing means all his deeds. And purifying them is making them pure, sincere and performed in the most complete ways, and cleansing them of what invalidates, spoils and diminishes them, of shirk, show, hypocrisy, conceit, arrogance, heedlessness and the like of what the servant is commanded to avoid in his acts of worship, and that includes cleansing clothes of impurity, for that is part of completing the purification of deeds, especially in prayer, about which many scholars said that removing impurity from it is a condition. And it may be that what is meant by his clothing is the known clothing, that he is commanded to cleanse it of all impurities at all times, especially when entering the prayers."}],"h":[]},{"id":"tahur","ch":"tahara","t":"وأنزلنا من السماء ماء طهوراً","r":[25,48,49],"n":"ذكر الله أنه أنزل من السماء ماءً طهوراً، وبيّن السعدي أنه يطهّر من الحدث والخبث، وأن فيه بركة، وأنه رزق للناس والأنعام.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":25,"ay":48,"x":"وأنۡزَلۡنا من السماءِ ماءً طَهوراً}: يطهِّر من الحدث والخَبَث، ويطهِّر من الغش والأدناس …","en":"\"and We sent down from the sky pure water\": it purifies from ritual impurity and filth, and purifies from deceit and defilements"}],"h":[]},{"id":"radaa","ch":"hayat","t":"والوالدات يرضعن أولادهن حولين كاملين","r":[2,233,233],"n":"جعل الله مدة الرضاعة الكاملة حولين لمن أراد أن يتم الرضاعة. وبيّن السعدي أن الطفل إذا تم له حولان تم رضاعه وصار اللبن بعد ذلك بمنزلة سائر الأغذية.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":2,"ay":233,"x":"هذا خبر بمعنى الأمر تنزيلاً له منزلة المتقرر الذي لا يحتاج إلى أمر بأن {يرضعن أولادهن حولين}؛ ولما كان الحول يطلق على الكامل وعلى معظم الحول قال:{كاملين لمن أراد أن يتم الرضاعة}؛ فإذا تم للرضيع حولان فقد تم رضاعه وصار اللبن بعد ذلك بمنزلة سائر الأغذية، فلهذا كان الرضاع بعد الحولين غير معتبر لا يُحَرِّم.","en":"This is a report with the meaning of a command, giving it the status of something established that needs no command, that \"mothers shall breastfeed their children for two full years\"; and since the year may refer to a complete year or to most of a year, He said: \"complete, for whoever wishes to complete the nursing\". So when two years are complete for the infant, his suckling is complete and the milk after that becomes like other foods, and therefore suckling after two years is not counted and does not make marriage forbidden."}],"h":[]},{"id":"hamlfisal","ch":"hayat","t":"وحمله وفصاله ثلاثون شهراً","r":[46,15,15],"n":"ذكر الله ما تحمّلته الأم من الحمل والولادة والرضاعة، وجعل «حمله وفصاله» ثلاثين شهراً. وفسّره السعدي بأن الحمل نحو تسعة أشهر والباقي للرضاع، وهذا هو الغالب.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":46,"ay":15,"x":"فذكر ما تحمَّلته الأمُّ من ولدها، وما قاستْه من المكاره وقت حَمْلِها، ثم مشقَّة ولادتها المشقَّة الكبيرة، ثم مشقَّة الرضاع وخدمة الحضانة، وليست المذكوراتُ مدة يسيرة ساعة أو ساعتين، وإنما ذلك مدة طويلة قدرها {ثلاثون شهراً}: للحمل تسعة أشهر ونحوها، والباقي للرضاع، هذا الغالب …","en":"then He mentioned what the mother bore from her child and what hardships she endured during her pregnancy, then the great hardship of her delivery, then the hardship of nursing and the service of care, and what is mentioned is not a short time of an hour or two, but a long period whose measure is \"thirty months\": nine months or so for pregnancy, and the rest for nursing; this is the usual case"}],"h":[]},{"id":"wahn","ch":"hayat","t":"حملته أمه وهناً على وهن","r":[31,14,14],"n":"وصّى الله الإنسان بوالديه وذكر ما تحمّلته الأم: «وهناً على وهن» وفصاله في عامين. وفسّره السعدي بالمشقة المتتابعة من الوحم والمرض والضعف والثقل ثم وجع الولادة.","hd":0,"qs":[{"w":"السعدي","bk":"saadi","s":31,"ay":14,"x":"ثمَّ ذَكَرَ السببَ الموجبَ لبرِّ الوالدين في الأم، فقال:{حَمَلَتۡه أمُّه وهناً على وهنٍ}؛ أي: مشقة على مشقة؛ فلا تزال تلاقي المشاقَّ من حين يكون نطفةً من الوحم والمرض والضعف والثقل وتغير الحال، ثم وجع الولادة ذلك الوجع الشديد، ثم {فصالُهُ في عامينِ}: وهو ملازمٌ لحضانة أمِّه وكفالتها ورضاعها.","en":"Then He mentioned the cause that obliges kindness to parents in the case of the mother, so He said: \"his mother carried him in weakness upon weakness\", that is, hardship upon hardship; she keeps meeting hardships from the time he is a drop of fluid, of morning sickness, illness, weakness, heaviness and change of condition, then the pain of delivery, that severe pain, then \"his weaning is in two years\": and he is bound to his mother's care, upkeep and nursing."}],"h":[]}],"ay":{"161":"وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ","162":"ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ","163":"أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ","174":"يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ","189":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","190":"أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","191":"شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ","201":"وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ","225":"۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ","228":"وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ","239":"۞ وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ","431":"وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ","521":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا","671":"حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","674":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ","984":"۞ يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ","1342":"لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ","1420":"يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ","1662":"وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ","1682":"يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ","1734":"ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ","1966":"وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّٰرِبِينَ","1968":"وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ","1969":"ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ","2274":"وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا","2275":"فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا","2348":"طه","2349":"مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ","2512":"أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ","2692":"وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ","2902":"وَهُوَ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ طَهُورٗا","2903":"لِّنُحۡـِۧيَ بِهِۦ بَلۡدَةٗ مَّيۡتٗا وَنُسۡقِيَهُۥ مِمَّا خَلَقۡنَآ أَنۡعَٰمٗا وَأَنَاسِيَّ كَثِيرٗا","3009":"ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ","3010":"وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ","3011":"وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ","3012":"وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ","3482":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ","4010":"وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ","4011":"ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ","4012":"وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ","4013":"وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ","4110":"۞ قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","4524":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ","4586":"هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","5218":"فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا","5219":"وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا","5498":"وَثِيَابَكَ فَطَهِّرۡ","5680":"وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا","5681":"وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا","5682":"وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا","6094":"فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا","6095":"إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا"},"nay":53,"nhd":12};
